Given two arrays a[] and b[], check if they are disjoint, i.e., there is no element common between both the arrays.Examples: Input: a[] = [12, 34, 11, 9, 3], b[] = [2, 1, 3, 5] Output: FalseExplanation: 3 is common in both the arrays.Input: a[] = [12, 34, 11, 9, 3], b[] = [7, 2, 1, 5] Output: True Explanation: There is no common element in both the arrays.Try It YourselfTable of Content[Naive Approach] Using Two Nested Loops - O(n * m) Time and O(1) Space[Better Approach] Using Sorting and Two Pointer - O(n Log n + m Log m) Time and O(1) Space[Expected Approach] Using Hashing - O(n + m) Time and O(n) Space[Naive Approach] Using Two Nested Loops - O(n * m) Time and O(1) SpaceThe simplest approach is to iterate through every element of the first array and search it in another array, if any element is found, the given arrays are not disjoint.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool areDisjoint(vector<int> &a, vector<int> &b) {

    // Take every element of array a 
    // and search it in array b
    for(int i = 0; i < a.size(); i++) {
        for(int j = 0; j < b.size(); j++) {

            // If any common element is found
            // given arrays are not disjoint
            if(a[i] == b[j])
                return false;
        }
    }

    return true;
}

int main() {
    vector<int> a = {12, 34, 11, 9, 3};
    vector<int> b = {7, 2, 1, 5};

    if(areDisjoint(a, b))
        cout << "True";
    else
        cout << "False";

    return 0;
}


