OutputTrue[Better Approach] Using Sorting and Two Pointer - O(n Log n + m Log m) Time and O(1) SpaceFirst, we sort both the arrays. Then, we initialize pointers at the beginning of both the arrays. If the value at one pointer is smaller than the value at the other, we increment that pointer. If at any point, the values at both pointers become equal, the arrays are not disjoint. If no value matches during the whole traversal, then the given arrays are disjoint.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool areDisjoint(vector<int> &a, vector<int> &b) {

    // Sorting both the arrays
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    // Initializing pointers at the  
    // beginning of both the arrays
    int i = 0, j = 0;

    while(i < a.size() && j < b.size()) {

        // If any common element is found, then
        // given arrays are not disjoint
        if(a[i] == b[j])
            return false;

        // Incrementing the pointer  
        // having smaller value
        if(a[i] < b[j])
            i++;
        else
            j++;
    }

    return true;
}

int main() {
    vector<int> a = {12, 34, 11, 9, 3};
    vector<int> b = {7, 2, 1, 5};

    if(areDisjoint(a, b))
        cout << "True";
    else
        cout << "False";

    return 0;
}


